// ─────────────────────────────────────────────────────────────────────────────
// Config & Safety Gate
// Reads every runtime setting from environment variables: the three custom
// object types (Parent → Child → Asset), the association type IDs for each
// direction, remediation options, thresholds and safety flags.
// SAFE-BY-DEFAULT: a missing, blank or unrecognised flag resolves to its safe
// value, so a fresh import performs zero HubSpot mutations and sends nothing.
// Secret VALUES are never copied into the item: only "is present" booleans.
// ─────────────────────────────────────────────────────────────────────────────
let envAccessible = true;
try { void $env.SANDBOX_MODE; } catch (e) { envAccessible = false; }

const readEnv = (key) => {
  if (!envAccessible) return undefined;
  try {
    const v = $env[key];
    return v === undefined || v === null ? undefined : String(v).trim();
  } catch (e) {
    return undefined;
  }
};

const warnings = [];
if (!envAccessible) warnings.push('Environment access is blocked (N8N_BLOCK_ENV_ACCESS_IN_NODE=true). All safe defaults were applied.');

const flag = (key, safeDefault) => {
  const raw = readEnv(key);
  if (raw === undefined || raw === '') return safeDefault;
  const v = raw.toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  warnings.push(`${key} has an unrecognised value; using safe default (${safeDefault}).`);
  return safeDefault;
};
const num = (key, def, min, max) => {
  const raw = readEnv(key);
  if (raw === undefined || raw === '') return def;
  const n = Number(raw);
  if (!Number.isFinite(n) || n < min || n > max) { warnings.push(`${key} must be a number between ${min} and ${max}; using default ${def}.`); return def; }
  return n;
};
const str = (key, def, pattern) => {
  const raw = readEnv(key);
  if (!raw) return def;
  if (pattern && !pattern.test(raw)) { warnings.push(`${key} has an invalid format; using default.`); return def; }
  return raw;
};
const oneOf = (key, def, allowed) => {
  const raw = (readEnv(key) || '').toLowerCase();
  if (!raw) return def;
  if (allowed.includes(raw)) return raw;
  warnings.push(`${key} must be one of ${allowed.join(', ')}; using default ${def}.`);
  return def;
};

// ── Run clock
let runDate = new Date();
const tsOverride = readEnv('RUN_TIMESTAMP_OVERRIDE');
if (tsOverride) {
  const d = new Date(tsOverride);
  if (Number.isNaN(d.getTime())) warnings.push('RUN_TIMESTAMP_OVERRIDE is not a valid ISO date; using current time.');
  else runDate = d;
}

// ── Safety flags (safe defaults)
const sandboxRequested = flag('SANDBOX_MODE', true);
const dryRun = flag('DRY_RUN', true);
const hubspotMutationsEnabled = flag('HUBSPOT_MUTATIONS_ENABLED', false);
const sendSlackAlerts = flag('SEND_SLACK_ALERTS', false);
const sendOpsAlerts = flag('SEND_OPS_ALERTS', false);

// ── Secret presence only
const hasHubspotToken = Boolean(readEnv('HUBSPOT_ACCESS_TOKEN'));
const hasSlackWebhook = /^https:\/\//i.test(readEnv('SLACK_ALERT_WEBHOOK_URL') || '');
const hasAlertWebhook = /^https:\/\//i.test(readEnv('ALERT_WEBHOOK_URL') || '');

// ── Hierarchy definition (placeholders by default)
const TYPE_RE = /^(p\d+_[a-z0-9_]+|2-\d+)$/;
const TYPE_ID_RE = /^2-\d+$/;
const PROP_RE = /^[a-z][a-z0-9_]{0,99}$/;
const nameProperty = str('RECORD_NAME_PROPERTY', 'name', PROP_RE);
const keyProperty = str('RECORD_KEY_PROPERTY', 'external_id', PROP_RE);
const levels = {
  parent: {
    key: 'parent', label: str('PARENT_LABEL', 'Parent'),
    objectType: str('HUBSPOT_PARENT_OBJECT_TYPE', 'p99000001_parent_account', TYPE_RE),
    objectTypeId: str('HUBSPOT_PARENT_OBJECT_TYPE_ID', '2-99000101', TYPE_ID_RE),
    hintProperty: null,
  },
  child: {
    key: 'child', label: str('CHILD_LABEL', 'Child'),
    objectType: str('HUBSPOT_CHILD_OBJECT_TYPE', 'p99000001_child_project', TYPE_RE),
    objectTypeId: str('HUBSPOT_CHILD_OBJECT_TYPE_ID', '2-99000102', TYPE_ID_RE),
    hintProperty: str('CHILD_PARENT_HINT_PROPERTY', 'parent_external_id', PROP_RE),
  },
  asset: {
    key: 'asset', label: str('ASSET_LABEL', 'Asset'),
    objectType: str('HUBSPOT_ASSET_OBJECT_TYPE', 'p99000001_asset_unit', TYPE_RE),
    objectTypeId: str('HUBSPOT_ASSET_OBJECT_TYPE_ID', '2-99000103', TYPE_ID_RE),
    hintProperty: str('ASSET_CHILD_HINT_PROPERTY', 'child_external_id', PROP_RE),
  },
};
const distinctTypes = new Set(Object.values(levels).map((l) => l.objectType));
if (distinctTypes.size !== 3) warnings.push('Parent, Child and Asset object types must be three distinct object types.');

// Association definitions: "up" = lower → upper, "down" = upper → lower.
const relations = [
  {
    key: 'parent_child', upper: 'parent', lower: 'child',
    upTypeId: Math.floor(num('PARENT_CHILD_UP_TYPE_ID', 901, 1, 1e9)),
    downTypeId: Math.floor(num('PARENT_CHILD_DOWN_TYPE_ID', 902, 1, 1e9)),
    maxUpperPerLower: Math.floor(num('MAX_PARENTS_PER_CHILD', 1, 1, 1000)),
    requireUpper: flag('REQUIRE_PARENT_FOR_CHILD', true),
    upDirection: 'child_to_parent', downDirection: 'parent_to_child',
  },
  {
    key: 'child_asset', upper: 'child', lower: 'asset',
    upTypeId: Math.floor(num('CHILD_ASSET_UP_TYPE_ID', 903, 1, 1e9)),
    downTypeId: Math.floor(num('CHILD_ASSET_DOWN_TYPE_ID', 904, 1, 1e9)),
    maxUpperPerLower: Math.floor(num('MAX_CHILDREN_PER_ASSET', 1, 1, 1000)),
    requireUpper: flag('REQUIRE_CHILD_FOR_ASSET', true),
    upDirection: 'asset_to_child', downDirection: 'child_to_asset',
  },
];

// ── Remediation options (mutations still require every gate below)
const ACTIONS = ['create_missing_association', 'archive_dangling_association', 'flag_records'];
const remediationActions = (readEnv('REMEDIATION_ACTIONS') || 'flag_records')
  .split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const unknownActions = remediationActions.filter((a) => !ACTIONS.includes(a));
if (unknownActions.length) warnings.push(`REMEDIATION_ACTIONS contains unknown action(s) ignored: ${unknownActions.join(', ')}.`);
const enabledActions = ACTIONS.filter((a) => remediationActions.includes(a));

// ── Live readiness and hard gates
let sandboxMode = sandboxRequested;
if (!sandboxRequested && !hasHubspotToken) {
  sandboxMode = true;
  warnings.push('SANDBOX_MODE=false but HUBSPOT_ACCESS_TOKEN is missing. Forced back to sandbox fixtures.');
}
if (!sandboxRequested && distinctTypes.size !== 3) {
  sandboxMode = true;
  warnings.push('Live mode refused: object types are not distinct. Forced back to sandbox fixtures.');
}

const allowHubspotMutations = !sandboxMode && !dryRun && hubspotMutationsEnabled && hasHubspotToken && enabledActions.length > 0;
const allowSlackSend = sendSlackAlerts && !dryRun && hasSlackWebhook;
const allowOpsAlert = sendOpsAlerts && !dryRun && hasAlertWebhook;
const mutationBlockedReason = allowHubspotMutations ? null
  : sandboxMode ? 'sandbox_mode'
  : dryRun ? 'dry_run'
  : !hubspotMutationsEnabled ? 'hubspot_mutations_disabled'
  : !hasHubspotToken ? 'missing_hubspot_token'
  : 'no_remediation_actions_enabled';

// ── Live search bodies (paginated via the HTTP node's "after" body parameter)
const searchBody = (lvl) => ({
  filterGroups: [],
  properties: [...new Set([nameProperty, keyProperty, 'integrity_status', 'hs_lastmodifieddate', lvl.hintProperty].filter(Boolean))],
  sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }],
  limit: 100,
});

const modeLabel = sandboxMode ? 'SANDBOX' : (dryRun ? 'LIVE-DRY-RUN' : 'LIVE');
const stamp = runDate.toISOString().replace(/[-:]/g, '').replace(/\..+$/, '').replace('T', '-');
const execId = (typeof $execution !== 'undefined' && $execution && $execution.id) ? String($execution.id) : 'manual';

return [{
  json: {
    runId: `cmav-${stamp}-${execId}`,
    runStartedAt: runDate.toISOString(),
    runDate: runDate.toISOString().slice(0, 10),
    modeLabel,
    envAccessible,

    sandboxRequested,
    sandboxMode,
    dryRun,
    hubspotMutationsEnabled,
    sendSlackAlerts,
    sendOpsAlerts,
    allowHubspotMutations,
    allowSlackSend,
    allowOpsAlert,
    mutationBlockedReason,
    secretsPresent: { hasHubspotToken, hasSlackWebhook, hasAlertWebhook },

    hubspotPortalId: str('HUBSPOT_PORTAL_ID', '99000001', /^\d{1,12}$/),
    hubspotAppBaseUrl: str('HUBSPOT_APP_BASE_URL', 'https://app.hubspot.com', /^https:\/\/app(-[a-z0-9]+)?\.hubspot\.com$/),
    nameProperty,
    keyProperty,
    levels,
    relations,
    searchBodies: { parent: searchBody(levels.parent), child: searchBody(levels.child), asset: searchBody(levels.asset) },
    searchMaxPages: Math.floor(num('SEARCH_MAX_PAGES', 100, 1, 100)),
    associationBatchSize: Math.floor(num('ASSOCIATION_BATCH_SIZE', 100, 1, 1000)),
    mutationBatchSize: Math.floor(num('MUTATION_BATCH_SIZE', 100, 1, 100)),

    associationCategory: oneOf('ASSOCIATION_CATEGORY', 'user_defined', ['user_defined', 'hubspot_defined']).toUpperCase(),
    strictAssociationTypes: flag('STRICT_ASSOCIATION_TYPES', true),
    checkBidirectional: flag('CHECK_BIDIRECTIONAL_ASSOCIATIONS', true),
    flagEmptyParents: flag('FLAG_EMPTY_PARENTS', true),

    enabledActions,
    maxMutationsPerRun: Math.floor(num('MAX_MUTATIONS_PER_RUN', 100, 0, 10000)),
    mutationAbortOrphanRatePct: num('MUTATION_ABORT_ORPHAN_RATE_PCT', 50, 1, 100),
    orphanRateAlertThresholdPct: num('ORPHAN_RATE_ALERT_THRESHOLD_PCT', 5, 0, 100),
    alertMinSeverity: oneOf('ALERT_MIN_SEVERITY', 'medium', ['low', 'medium', 'high', 'critical']),

    warnings,
  },
}];

