if (!FIXTURE || !FIXTURE.graph || !FIXTURE.graph.records || !FIXTURE.graph.associations) {
  throw new Error('Sandbox fixture must contain graph.records and graph.associations.');
}
return [{ json: { ...FIXTURE.graph, source: 'sandbox' }, pairedItem: { item: 0 } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Live Fetch Plan
// One item per hierarchy level. Drives the read-only schema preflight
// (GET /crm/v3/schemas/{objectType}, scope crm.schemas.custom.read), which
// confirms the configured association type IDs exist before anything is
// trusted or repaired.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
return ['parent', 'child', 'asset'].map((levelKey) => ({
  json: { levelKey, objectType: cfg.levels[levelKey].objectType },
  pairedItem: { item: 0 },
}));

// ─────────────────────────────────────────────────────────────────────────────
// Build Association Read Batches
// Collects the paginated search results for all three levels and builds
// CRM v4 association batch/read requests for every direction:
//   child → parent, parent → child, asset → child, child → asset
// Reading both directions lets the engine detect asymmetric links.
// If there is nothing to read, emits a single { noReads: true } marker.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const SEARCH_NODES = { parent: 'HubSpot: Search Parent Records', child: 'HubSpot: Search Child Records', asset: 'HubSpot: Search Asset Records' };

const idsFor = (levelKey) => {
  const ids = [];
  for (const page of $(SEARCH_NODES[levelKey]).all()) {
    const body = page.json || {};
    if (body.error || !Array.isArray(body.results)) continue;
    for (const r of body.results) if (r && r.id) ids.push(String(r.id));
  }
  return [...new Set(ids)];
};
const ids = { parent: idsFor('parent'), child: idsFor('child'), asset: idsFor('asset') };

const directions = [];
for (const rel of cfg.relations) {
  directions.push({ direction: rel.upDirection, fromLevel: rel.lower, toLevel: rel.upper });
  if (cfg.checkBidirectional) directions.push({ direction: rel.downDirection, fromLevel: rel.upper, toLevel: rel.lower });
}

const size = cfg.associationBatchSize;
const out = [];
for (const d of directions) {
  const fromType = cfg.levels[d.fromLevel].objectType;
  const toType = cfg.levels[d.toLevel].objectType;
  const list = ids[d.fromLevel];
  for (let i = 0; i < list.length; i += size) {
    out.push({
      json: {
        noReads: false,
        direction: d.direction,
        fromLevel: d.fromLevel,
        toLevel: d.toLevel,
        path: `/crm/v4/associations/${fromType}/${toType}/batch/read`,
        body: { inputs: list.slice(i, i + size).map((id) => ({ id })) },
      },
      pairedItem: { item: 0 },
    });
  }
}

if (out.length === 0) return [{ json: { noReads: true, direction: null, recordCounts: { parent: ids.parent.length, child: ids.child.length, asset: ids.asset.length } } }];
return out;

// ─────────────────────────────────────────────────────────────────────────────
// Assemble Live Association Graph
// Rebuilds the exact graph shape the sandbox fixture uses:
//   { levels, schemas, records{parent,child,asset}, associations{direction:{results}}, fetchMeta }
// Responses are paired with their requests by index. Any fetch error or a
// truncated search is recorded in fetchMeta so the engine can refuse to
// trust "dangling" verdicts or to mutate anything.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const SEARCH_NODES = { parent: 'HubSpot: Search Parent Records', child: 'HubSpot: Search Child Records', asset: 'HubSpot: Search Asset Records' };
const errText = (e) => (typeof e === 'string' ? e : (e && (e.message || e.description)) || 'request failed').toString().slice(0, 300);

const fetchMeta = { truncated: {}, pages: {}, errors: [] };
const records = {};
for (const [levelKey, nodeName] of Object.entries(SEARCH_NODES)) {
  const pages = $(nodeName).all().map((p) => p.json || {});
  const seen = new Map();
  let truncated = false;
  pages.forEach((body, i) => {
    if (body.error) { fetchMeta.errors.push({ stage: `search_${levelKey}`, message: errText(body.error) }); return; }
    for (const r of body.results || []) if (r && r.id) seen.set(String(r.id), { id: String(r.id), properties: r.properties || {}, archived: Boolean(r.archived) });
    if (i === pages.length - 1 && body.paging && body.paging.next && body.paging.next.after) truncated = true;
  });
  const total = pages.reduce((m, b) => Math.max(m, Number(b.total) || 0), 0);
  if (total > seen.size) truncated = true;
  records[levelKey] = [...seen.values()];
  fetchMeta.truncated[levelKey] = truncated;
  fetchMeta.pages[levelKey] = pages.length;
}

// Schema preflight responses (paired with Build Live Fetch Plan by index)
const schemas = {};
const plan = $('Build Live Fetch Plan').all();
$('HubSpot: Read Schema Definitions').all().forEach((r, i) => {
  const levelKey = plan[i] ? plan[i].json.levelKey : null;
  if (!levelKey) return;
  const body = r.json || {};
  if (body.error) { fetchMeta.errors.push({ stage: `schema_${levelKey}`, message: errText(body.error), nonBlocking: true }); schemas[levelKey] = null; return; }
  schemas[levelKey] = { objectTypeId: body.objectTypeId || body.id || null, fullyQualifiedName: body.fullyQualifiedName || null, associations: Array.isArray(body.associations) ? body.associations : [] };
});

// Association reads
const associations = {};
const first = $input.first().json || {};
if (!first.noReads) {
  const requests = $('Build Association Read Batches').all();
  const responses = $input.all();
  if (responses.length !== requests.length) throw new Error(`Association response count (${responses.length}) does not match request count (${requests.length}).`);
  responses.forEach((r, i) => {
    const req = requests[i].json;
    const body = r.json || {};
    const bucket = associations[req.direction] || (associations[req.direction] = { status: 'COMPLETE', results: [] });
    if (body.error) {
      bucket.status = 'ERROR';
      fetchMeta.errors.push({ stage: `associations_${req.direction}`, message: errText(body.error) });
      return;
    }
    for (const row of body.results || []) {
      bucket.results.push(row);
      if (row.paging && row.paging.next) fetchMeta.errors.push({ stage: `associations_${req.direction}`, message: `Record ${row.from && row.from.id} has more than one page of associations; only the first page was read.`, nonBlocking: true });
    }
    // HubSpot reports records with zero associations under errors (e.g. NO_ASSOCIATIONS_FOUND) — that is data, not failure.
  });
}

return [{
  json: {
    source: 'live',
    levels: Object.fromEntries(Object.entries(cfg.levels).map(([k, l]) => [k, { objectType: l.objectType, objectTypeId: l.objectTypeId, label: l.label }])),
    schemas,
    records,
    associations,
    fetchMeta,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Association Integrity & Orphan Detection Engine  (Run Once for All Items)
// Input: one association graph (sandbox fixture or live HubSpot reads).
// 1. Indexes Parent, Child and Asset records and both read directions of
//    each relation (child↔parent, asset↔child).
// 2. Detects:
//    • orphan_child / orphan_asset      – no valid link to the level above
//    • dangling_association             – link points to a deleted/archived ID
//    • broken_chain                     – asset whose only children are orphans
//    • cardinality_violation            – more parents/children than allowed
//    • association_label_mismatch       – link exists without the expected type ID
//    • asymmetric_association           – seen in one read direction only
//    • empty_parent                     – parent with no children (informational)
//    • association_definition_missing   – configured type ID absent from schema
//    • audit_incomplete                 – a direction could not be read
// 3. Plans remediation: create missing associations (only from an exact,
//    unique hint-property match), archive verified dangling links, and flag
//    records with integrity_status — all subject to the mutation guard.
// Pure JavaScript: no network, no require(), runs identically in the simulator.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const g = $input.first().json || {};
const LEVELS = ['parent', 'child', 'asset'];
const SEVERITIES = ['low', 'medium', 'high', 'critical'];
const sevRank = (s) => SEVERITIES.indexOf(s);
const maxSev = (a, b) => (sevRank(a) >= sevRank(b) ? a : b);
const fetchMeta = g.fetchMeta || { truncated: {}, pages: {}, errors: [] };
const blockingFetchErrors = (fetchMeta.errors || []).filter((e) => !e.nonBlocking);

// ── Index records ───────────────────────────────────────────────────────────
const objectTypeIdOf = (lvl) => (g.levels && g.levels[lvl] && g.levels[lvl].objectTypeId) || cfg.levels[lvl].objectTypeId;
const recordUrl = (lvl, id) => `${cfg.hubspotAppBaseUrl}/contacts/${cfg.hubspotPortalId}/record/${objectTypeIdOf(lvl)}/${id}`;
const byId = {};
for (const lvl of LEVELS) {
  byId[lvl] = new Map();
  for (const r of (g.records && g.records[lvl]) || []) {
    if (!r || r.id === undefined || r.id === null || r.archived) continue;
    const p = r.properties || {};
    const hintProp = cfg.levels[lvl].hintProperty;
    const clean = (v) => (v === null || v === undefined || String(v).trim() === '' ? null : String(v).trim());
    byId[lvl].set(String(r.id), {
      id: String(r.id), level: lvl,
      name: clean(p[cfg.nameProperty]) || `${cfg.levels[lvl].label} ${r.id}`,
      key: clean(p[cfg.keyProperty]),
      hint: hintProp ? clean(p[hintProp]) : null,
      priorStatus: clean(p.integrity_status),
    });
  }
}
const keyIndex = {};
for (const lvl of LEVELS) {
  keyIndex[lvl] = new Map();
  for (const r of byId[lvl].values()) if (r.key) { const k = r.key.toLowerCase(); keyIndex[lvl].set(k, [...(keyIndex[lvl].get(k) || []), r]); }
}

// ── Parse association reads (CRM v4 batch/read shape) ────────────────────────
const parseDirection = (dir) => {
  const bucket = g.associations ? g.associations[dir] : undefined;
  const map = new Map();
  if (!bucket || bucket.status === 'ERROR') return { read: false, map };
  for (const row of bucket.results || []) {
    const fromId = row && row.from && row.from.id !== undefined ? String(row.from.id) : null;
    if (!fromId) continue;
    const list = map.get(fromId) || [];
    for (const t of row.to || []) {
      const types = (t.associationTypes || []).map((a) => Number(a.typeId)).filter(Number.isFinite);
      list.push({ toId: String(t.toObjectId), types });
    }
    map.set(fromId, list);
  }
  return { read: true, map };
};

// ── Issue collection ─────────────────────────────────────────────────────────
const issues = [];
const issueKeys = new Set();
const addIssue = (i) => {
  const id = `${i.code}:${i.recordId || '-'}:${i.relatedId || '-'}`;
  if (issueKeys.has(id)) return;
  issueKeys.add(id);
  issues.push({ id, ...i });
};
const recIssues = new Map(); // `${level}:${id}` -> Set(codes)
const tagRecord = (lvl, id, code) => { const k = `${lvl}:${id}`; recIssues.set(k, (recIssues.get(k) || new Set()).add(code)); };

const creates = [];   // { fromLevel, toLevel, typeId, fromId, toId, reason }
const archives = [];  // { fromLevel, toLevel, fromId, toId }
const orphanSet = { child: new Set(), asset: new Set() };
const validUppers = { child: new Map(), asset: new Map() }; // lowerId -> Set(upperIds)
const auditIncomplete = [];

// ── Schema preflight: configured association type IDs must exist ────────────
const schemaCheck = { ok: true, verified: true, missing: [] };
for (const rel of cfg.relations) {
  for (const [lvl, typeId, dir] of [[rel.lower, rel.upTypeId, rel.upDirection], [rel.upper, rel.downTypeId, rel.downDirection]]) {
    const schema = g.schemas ? g.schemas[lvl] : null;
    if (!schema) { schemaCheck.verified = false; continue; }
    const found = (schema.associations || []).some((a) => String(a.id) === String(typeId));
    if (!found) {
      schemaCheck.ok = false;
      schemaCheck.missing.push({ level: lvl, direction: dir, typeId });
      addIssue({ code: 'association_definition_missing', severity: 'critical', level: lvl, recordId: null, recordName: cfg.levels[lvl].label,
        message: `Association type ID ${typeId} (${dir}) is not defined on ${cfg.levels[lvl].objectType}. Fix the *_TYPE_ID env vars before trusting label checks or repairs.`,
        remediation: { action: 'manual_review', status: 'manual_review', detail: 'Check GET /crm/v4/associations/{from}/{to}/labels and update the env vars.' } });
    }
  }
}

// ── Relation checks ─────────────────────────────────────────────────────────
for (const rel of cfg.relations) {
  const lowerLbl = cfg.levels[rel.lower].label; const upperLbl = cfg.levels[rel.upper].label;
  const up = parseDirection(rel.upDirection);
  const down = parseDirection(rel.downDirection);
  const lowerCount = byId[rel.lower].size;
  const upReadable = up.read || lowerCount === 0;

  if (!upReadable) {
    auditIncomplete.push(rel.upDirection);
    addIssue({ code: 'audit_incomplete', severity: 'critical', level: rel.lower, recordId: null, recordName: lowerLbl,
      message: `Could not read ${rel.upDirection} associations; orphan detection for ${lowerLbl} records was skipped.`,
      remediation: { action: 'manual_review', status: 'blocked', detail: 'Re-run after resolving the fetch error. All mutations are blocked for this run.' } });
  }

  const edges = new Map();
  const edge = (lowerId, upperId) => {
    const k = `${lowerId}|${upperId}`;
    if (!edges.has(k)) edges.set(k, { lowerId, upperId, up: false, down: false, upTypes: new Set(), downTypes: new Set() });
    return edges.get(k);
  };
  for (const [fromId, list] of up.map) for (const t of list) { const e = edge(fromId, t.toId); e.up = true; t.types.forEach((x) => e.upTypes.add(x)); }
  for (const [fromId, list] of down.map) for (const t of list) { const e = edge(t.toId, fromId); e.down = true; t.types.forEach((x) => e.downTypes.add(x)); }

  const valid = new Map(); // lowerId -> Set(upperId)
  const unverifiedLower = new Set(); // lower records whose link target may just be unfetched
  for (const e of edges.values()) {
    const lower = byId[rel.lower].get(e.lowerId);
    const upper = byId[rel.upper].get(e.upperId);
    if (!lower && !upper) continue;
    if (!lower || !upper) {
      const missingLevel = upper ? rel.lower : rel.upper;
      const existing = lower || upper;
      const missingId = upper ? e.lowerId : e.upperId;
      const searchFailed = blockingFetchErrors.some((x) => x.stage === `search_${missingLevel}`);
      const verified = !fetchMeta.truncated[missingLevel] && !searchFailed;
      const fromLevel = existing.level; const toLevel = missingLevel;
      addIssue({ code: 'dangling_association', severity: 'high', level: existing.level, recordId: existing.id, recordName: existing.name,
        relatedLevel: missingLevel, relatedId: missingId, url: recordUrl(existing.level, existing.id),
        message: `${existing.name} is associated with ${cfg.levels[missingLevel].label} ${missingId}, which no longer exists (deleted or archived).`,
        remediation: verified
          ? { action: 'archive_dangling_association', status: 'planned', detail: `Archive ${fromLevel}→${toLevel} link ${existing.id} → ${missingId}.` }
          : { action: 'archive_dangling_association', status: 'unverified', detail: `${cfg.levels[missingLevel].label} search was truncated or failed; the target may simply not have been fetched.` } });
      tagRecord(existing.level, existing.id, 'dangling_association');
      if (verified) archives.push({ fromLevel, toLevel, fromId: existing.id, toId: missingId });
      else if (lower) unverifiedLower.add(lower.id);
      continue;
    }
    valid.set(e.lowerId, (valid.get(e.lowerId) || new Set()).add(e.upperId));

    if (cfg.checkBidirectional && up.read && down.read && e.up !== e.down) {
      addIssue({ code: 'asymmetric_association', severity: 'medium', level: rel.lower, recordId: lower.id, recordName: lower.name,
        relatedLevel: rel.upper, relatedId: upper.id, url: recordUrl(rel.lower, lower.id),
        message: `${lower.name} ↔ ${upper.name} appears only in the ${e.up ? rel.upDirection : rel.downDirection} read.`,
        remediation: { action: 'manual_review', status: 'manual_review', detail: 'Usually index lag; re-run. If it persists, remove and re-create the association in HubSpot.' } });
      tagRecord(rel.lower, lower.id, 'asymmetric_association');
    }
    if (cfg.strictAssociationTypes) {
      const upBad = e.up && !e.upTypes.has(rel.upTypeId);
      const downBad = e.down && !e.downTypes.has(rel.downTypeId);
      if (upBad || downBad) {
        const seen = [...new Set([...e.upTypes, ...e.downTypes])].join(', ') || 'none';
        addIssue({ code: 'association_label_mismatch', severity: 'medium', level: rel.lower, recordId: lower.id, recordName: lower.name,
          relatedLevel: rel.upper, relatedId: upper.id, url: recordUrl(rel.lower, lower.id),
          message: `${lower.name} → ${upper.name} uses association type ${seen}; expected ${rel.upTypeId} (${rel.upDirection}).`,
          remediation: { action: 'create_missing_association', status: 'planned', detail: `Add type ${rel.upTypeId} to the existing pair (additive; the old type is left in place).` } });
        tagRecord(rel.lower, lower.id, 'association_label_mismatch');
        creates.push({ fromLevel: rel.lower, toLevel: rel.upper, typeId: rel.upTypeId, fromId: lower.id, toId: upper.id, reason: 'add_expected_type' });
      }
    }
  }
  validUppers[rel.lower] = valid;

  // Orphans + cardinality
  if (upReadable) {
    for (const lower of byId[rel.lower].values()) {
      const ups = valid.get(lower.id) || new Set();
      if (ups.size === 0 && rel.requireUpper && unverifiedLower.has(lower.id)) continue; // target may exist beyond the truncated search
      if (ups.size === 0 && rel.requireUpper) {
        orphanSet[rel.lower].add(lower.id);
        let remediation;
        if (!lower.hint) remediation = { action: 'manual_review', status: 'manual_review', detail: `No ${cfg.levels[rel.lower].hintProperty} value; assign a ${upperLbl} manually.` };
        else {
          const matches = keyIndex[rel.upper].get(lower.hint.toLowerCase()) || [];
          if (matches.length === 1) {
            remediation = { action: 'create_missing_association', status: 'planned', detail: `Re-link to ${matches[0].name} (${cfg.keyProperty} = ${lower.hint}).`, targetId: matches[0].id, targetName: matches[0].name };
            creates.push({ fromLevel: rel.lower, toLevel: rel.upper, typeId: rel.upTypeId, fromId: lower.id, toId: matches[0].id, reason: 'orphan_hint_match' });
          } else if (matches.length > 1) {
            remediation = { action: 'manual_review', status: 'manual_review', detail: `Hint ${lower.hint} matches ${matches.length} ${upperLbl} records; resolve the duplicate key first.` };
          } else {
            remediation = { action: 'manual_review', status: 'manual_review', detail: `Hint ${lower.hint} matches no ${upperLbl} record.` };
          }
        }
        addIssue({ code: `orphan_${rel.lower}`, severity: 'high', level: rel.lower, recordId: lower.id, recordName: lower.name, url: recordUrl(rel.lower, lower.id),
          message: `${lower.name} has no valid ${upperLbl} association.`, remediation });
        tagRecord(rel.lower, lower.id, `orphan_${rel.lower}`);
      } else if (ups.size > rel.maxUpperPerLower) {
        const names = [...ups].map((id) => byId[rel.upper].get(id).name).join(', ');
        addIssue({ code: 'cardinality_violation', severity: 'medium', level: rel.lower, recordId: lower.id, recordName: lower.name, url: recordUrl(rel.lower, lower.id),
          message: `${lower.name} is linked to ${ups.size} ${upperLbl} records (max ${rel.maxUpperPerLower}): ${names}.`,
          remediation: { action: 'manual_review', status: 'manual_review', detail: `Decide which ${upperLbl} is authoritative; the validator never removes valid links automatically.` } });
        tagRecord(rel.lower, lower.id, 'cardinality_violation');
      }
    }
  }

  // Empty parents (informational, top relation only)
  if (rel.upper === 'parent' && cfg.flagEmptyParents && upReadable && !fetchMeta.truncated[rel.lower]) {
    const withChildren = new Set([...valid.values()].flatMap((s) => [...s]));
    for (const p of byId.parent.values()) {
      if (withChildren.has(p.id)) continue;
      addIssue({ code: 'empty_parent', severity: 'low', level: 'parent', recordId: p.id, recordName: p.name, url: recordUrl('parent', p.id),
        message: `${p.name} has no ${lowerLbl} records.`, remediation: { action: 'manual_review', status: 'informational', detail: 'Confirm whether this parent is still active.' } });
      tagRecord('parent', p.id, 'empty_parent');
    }
  }
}

// ── Broken chains: assets whose every linked child is itself orphaned ────────
for (const [assetId, childIds] of validUppers.asset) {
  const ids = [...childIds];
  if (ids.length && ids.every((cid) => orphanSet.child.has(cid))) {
    const asset = byId.asset.get(assetId);
    const childNames = ids.map((cid) => byId.child.get(cid).name).join(', ');
    addIssue({ code: 'broken_chain', severity: 'high', level: 'asset', recordId: asset.id, recordName: asset.name, relatedLevel: 'child', relatedId: ids[0], url: recordUrl('asset', asset.id),
      message: `${asset.name} cannot reach any ${cfg.levels.parent.label}: ${childNames} has no valid ${cfg.levels.parent.label} link.`,
      remediation: { action: 'manual_review', status: 'manual_review', detail: `Resolves automatically once ${childNames} is re-parented.` } });
    tagRecord('asset', asset.id, 'broken_chain');
  }
}

// ── Record status + flag plan (only records whose status changes) ───────────
const statusFor = (codes) => {
  if (!codes || codes.size === 0) return 'ok';
  if ([...codes].some((c) => c.startsWith('orphan_'))) return 'orphaned';
  if (codes.has('dangling_association')) return 'broken_link';
  if (codes.has('broken_chain')) return 'broken_chain';
  return 'needs_review';
};
const flags = [];
const healthy = {};
for (const lvl of LEVELS) {
  healthy[lvl] = 0;
  for (const r of byId[lvl].values()) {
    const codes = recIssues.get(`${lvl}:${r.id}`);
    const status = statusFor(codes);
    if (status === 'ok') healthy[lvl] += 1;
    const prior = r.priorStatus || 'ok';
    if (prior === status) continue;
    flags.push({ level: lvl, id: r.id, name: r.name, from: r.priorStatus, to: status,
      properties: { integrity_status: status, integrity_issue_codes: codes ? [...codes].sort().join(';') : '', integrity_last_checked: cfg.runDate, integrity_run_id: cfg.runId } });
  }
}

// ── Group mutations into HubSpot batch payloads ─────────────────────────────
const groupBy = (arr, keyFn) => arr.reduce((m, x) => { const k = keyFn(x); (m[k] = m[k] || []).push(x); return m; }, {});
const uniq = (arr, keyFn) => { const s = new Set(); return arr.filter((x) => { const k = keyFn(x); if (s.has(k)) return false; s.add(k); return true; }); };

const createGroups = Object.values(groupBy(uniq(creates, (c) => `${c.fromLevel}|${c.toLevel}|${c.typeId}|${c.fromId}|${c.toId}`), (c) => `${c.fromLevel}|${c.toLevel}|${c.typeId}`))
  .map((list) => ({ action: 'create_missing_association', fromLevel: list[0].fromLevel, toLevel: list[0].toLevel,
    path: `/crm/v4/associations/${cfg.levels[list[0].fromLevel].objectType}/${cfg.levels[list[0].toLevel].objectType}/batch/create`,
    count: list.length,
    inputs: list.map((c) => ({ types: [{ associationCategory: cfg.associationCategory, associationTypeId: c.typeId }], from: { id: c.fromId }, to: { id: c.toId } })),
    labels: list.map((c) => `${byId[c.fromLevel].get(c.fromId).name} → ${byId[c.toLevel].get(c.toId).name}`) }));

const archiveGroups = Object.values(groupBy(uniq(archives, (a) => `${a.fromLevel}|${a.toLevel}|${a.fromId}|${a.toId}`), (a) => `${a.fromLevel}|${a.toLevel}`))
  .map((list) => {
    const byFrom = groupBy(list, (a) => a.fromId);
    return { action: 'archive_dangling_association', fromLevel: list[0].fromLevel, toLevel: list[0].toLevel,
      path: `/crm/v4/associations/${cfg.levels[list[0].fromLevel].objectType}/${cfg.levels[list[0].toLevel].objectType}/batch/archive`,
      count: list.length,
      inputs: Object.entries(byFrom).map(([fromId, xs]) => ({ from: { id: fromId }, to: xs.map((x) => ({ id: x.toId })) })),
      labels: list.map((a) => `${byId[a.fromLevel].get(a.fromId).name} → deleted ${a.toId}`) };
  });

const flagGroups = Object.values(groupBy(flags, (f) => f.level)).map((list) => ({
  action: 'flag_records', fromLevel: list[0].level, toLevel: null,
  path: `/crm/v3/objects/${cfg.levels[list[0].level].objectType}/batch/update`,
  count: list.length,
  inputs: list.map((f) => ({ id: f.id, properties: f.properties })),
  labels: list.map((f) => `${f.name}: ${f.from || 'unset'} → ${f.to}`),
}));

// ── Stats, severity, mutation guard ─────────────────────────────────────────
const totalRecords = LEVELS.reduce((a, l) => a + byId[l].size, 0);
const healthyRecords = LEVELS.reduce((a, l) => a + healthy[l], 0);
const lowerTotal = byId.child.size + byId.asset.size;
const orphanTotal = orphanSet.child.size + orphanSet.asset.size;
const orphanRatePct = lowerTotal ? Math.round((orphanTotal / lowerTotal) * 10000) / 100 : 0;
const integrityScore = totalRecords ? Math.round((healthyRecords / totalRecords) * 1000) / 10 : 100;

const byCode = {};
for (const i of issues) byCode[i.code] = (byCode[i.code] || 0) + 1;
let runSeverity = issues.reduce((s, i) => maxSev(s, i.severity), 'low');
if (!issues.length) runSeverity = 'none';
if (orphanTotal > 0 && orphanRatePct >= cfg.orphanRateAlertThresholdPct) runSeverity = 'critical';

const enabled = new Set(cfg.enabledActions);
const allGroups = [...createGroups, ...archiveGroups, ...flagGroups];
const enabledGroups = allGroups.filter((gr) => enabled.has(gr.action));
const plannedCount = enabledGroups.reduce((a, gr) => a + gr.count, 0);
const reasons = [];
if (blockingFetchErrors.length) reasons.push(`fetch_errors: ${blockingFetchErrors.length} read(s) failed`);
const truncatedLevels = Object.keys(fetchMeta.truncated || {}).filter((k) => fetchMeta.truncated[k]);
if (truncatedLevels.length) reasons.push(`search_truncated: ${truncatedLevels.join(', ')} (raise SEARCH_MAX_PAGES or narrow the audit scope)`);
if (auditIncomplete.length) reasons.push(`audit_incomplete: ${auditIncomplete.join(', ')}`);
if (orphanRatePct > cfg.mutationAbortOrphanRatePct) reasons.push(`orphan_rate_abort: ${orphanRatePct}% > ${cfg.mutationAbortOrphanRatePct}% (likely a fetch or configuration problem, not real orphans)`);
if (plannedCount > cfg.maxMutationsPerRun) reasons.push(`mutation_budget_exceeded: ${plannedCount} planned > MAX_MUTATIONS_PER_RUN ${cfg.maxMutationsPerRun}`);
const createBlockedReason = !schemaCheck.ok ? 'association_definition_missing' : (!schemaCheck.verified && g.source === 'live' ? 'schema_unverified' : null);

const groupsWithStatus = allGroups.map((gr) => {
  let status = 'planned';
  if (!enabled.has(gr.action)) status = 'skipped_action_not_enabled';
  else if (reasons.length) status = 'blocked_by_guard';
  else if (gr.action === 'create_missing_association' && createBlockedReason) status = `blocked_${createBlockedReason}`;
  return { ...gr, status };
});

// Keep issue remediation statuses honest about what will actually happen.
for (const i of issues) {
  if (!i.remediation || !['create_missing_association', 'archive_dangling_association'].includes(i.remediation.action) || i.remediation.status !== 'planned') continue;
  if (!enabled.has(i.remediation.action)) i.remediation.status = 'not_enabled';
  else if (reasons.length) i.remediation.status = 'blocked';
  else if (i.remediation.action === 'create_missing_association' && createBlockedReason) i.remediation.status = 'blocked';
}

const SORT = { critical: 0, high: 1, medium: 2, low: 3 };
issues.sort((a, b) => SORT[a.severity] - SORT[b.severity] || a.code.localeCompare(b.code) || String(a.recordName).localeCompare(String(b.recordName)));

return [{
  json: {
    runId: cfg.runId,
    modeLabel: cfg.modeLabel,
    source: g.source || 'unknown',
    runSeverity,
    integrityScore,
    orphanRatePct,
    stats: {
      records: { parent: byId.parent.size, child: byId.child.size, asset: byId.asset.size, total: totalRecords },
      healthy: { ...healthy, total: healthyRecords },
      orphans: { child: orphanSet.child.size, asset: orphanSet.asset.size, total: orphanTotal },
      issuesTotal: issues.length,
      issuesByCode: byCode,
      issuesBySeverity: Object.fromEntries(SEVERITIES.map((s) => [s, issues.filter((i) => i.severity === s).length])),
    },
    issues,
    remediationPlan: {
      groups: groupsWithStatus,
      totals: {
        create_missing_association: createGroups.reduce((a, x) => a + x.count, 0),
        archive_dangling_association: archiveGroups.reduce((a, x) => a + x.count, 0),
        flag_records: flagGroups.reduce((a, x) => a + x.count, 0),
      },
      enabledActions: cfg.enabledActions,
      plannedEnabledCount: plannedCount,
    },
    mutationGuard: { blocked: reasons.length > 0, reasons, createBlockedReason },
    schemaCheck,
    fetchMeta,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// Build Remediation Batches
// Turns the engine's remediation plan into HubSpot batch requests, in a safe
// order: 1) create missing associations, 2) archive verified dangling links,
// 3) flag records (integrity_status). Chunks to MUTATION_BATCH_SIZE (≤ 100).
// allowWrite is true ONLY when the Config gate is open AND the mutation guard
// did not block. Always emits ≥ 1 item so the write gate always executes.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const engine = $input.first().json;
const size = Math.min(100, Math.max(1, Number(cfg.mutationBatchSize) || 100));
const ORDER = { create_missing_association: 0, archive_dangling_association: 1, flag_records: 2 };

const runnable = engine.remediationPlan.groups
  .filter((gr) => gr.status === 'planned')
  .sort((a, b) => ORDER[a.action] - ORDER[b.action]);

const batches = [];
for (const gr of runnable) {
  for (let i = 0; i < gr.inputs.length; i += size) {
    const inputs = gr.inputs.slice(i, i + size);
    batches.push({
      action: gr.action,
      fromLevel: gr.fromLevel,
      toLevel: gr.toLevel,
      path: gr.path,
      body: { inputs },
      count: gr.action === 'archive_dangling_association' ? inputs.reduce((a, x) => a + x.to.length, 0) : inputs.length,
      labels: gr.labels.slice(i, i + size),
    });
  }
}

const gateOpen = cfg.allowHubspotMutations === true && !engine.mutationGuard.blocked;
if (!gateOpen || batches.length === 0) {
  return [{
    json: {
      allowWrite: false,
      empty: batches.length === 0,
      blockedReason: !cfg.allowHubspotMutations ? cfg.mutationBlockedReason
        : engine.mutationGuard.blocked ? 'mutation_guard' : 'nothing_to_change',
      previewBatches: batches,
    },
  }];
}

return batches.map((b, i) => ({
  json: { allowWrite: true, batchIndex: i, batchCount: batches.length, ...b },
  pairedItem: { item: 0 },
}));

// ─────────────────────────────────────────────────────────────────────────────
// Collect Remediation Results
// Correlates each HubSpot batch response (in order) with its request.
// Association archive returns 204 (empty body) on success; create and update
// return { status, results, numErrors, errors }. Partial failures are
// reported, never thrown, so the summary and ops alert always run.
// ─────────────────────────────────────────────────────────────────────────────
const requests = $('Build Remediation Batches').all();
const responses = $input.all();
const byAction = {};
const failures = [];

responses.forEach((r, i) => {
  const req = requests[i] ? requests[i].json : { action: 'unknown', count: 0, batchIndex: i };
  const body = r.json || {};
  const a = byAction[req.action] || (byAction[req.action] = { attempted: 0, succeeded: 0, failed: 0 });
  a.attempted += req.count;
  if (body.error) {
    a.failed += req.count;
    const msg = typeof body.error === 'string' ? body.error : (body.error.message || 'request failed');
    failures.push({ batchIndex: req.batchIndex, action: req.action, path: req.path, message: String(msg).slice(0, 300) });
    return;
  }
  const errs = Array.isArray(body.errors) ? body.errors : [];
  const failed = Math.min(req.count, Number(body.numErrors) || errs.length || 0);
  a.failed += failed;
  a.succeeded += req.count - failed;
  errs.slice(0, 10).forEach((e) => failures.push({ batchIndex: req.batchIndex, action: req.action, path: req.path, message: String(e.message || e.category || 'record error').slice(0, 300) }));
});

const totals = Object.values(byAction).reduce((t, a) => ({ attempted: t.attempted + a.attempted, succeeded: t.succeeded + a.succeeded, failed: t.failed + a.failed }), { attempted: 0, succeeded: 0, failed: 0 });

return [{ json: { writeMode: 'live', batchesAttempted: responses.length, byAction, ...totals, failures, ok: failures.length === 0 } }];

// ─────────────────────────────────────────────────────────────────────────────
// Dry-Run Remediation Preview
// Reached whenever the mutation gate is closed. Lists exactly which HubSpot
// batch calls WOULD run, plus planned groups that were skipped or blocked.
// No network calls.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const engine = $('Association Integrity & Orphan Detection Engine').first().json;
const marker = $input.first().json;
const batches = marker.previewBatches || [];

return [{
  json: {
    writeMode: 'preview',
    blockedReason: marker.blockedReason,
    guardReasons: engine.mutationGuard.reasons,
    portalId: cfg.hubspotPortalId,
    wouldRun: batches.map((b) => ({ action: b.action, method: 'POST', endpoint: `https://api.hubapi.com${b.path}`, records: b.count, examples: b.labels.slice(0, 5) })),
    wouldChangeCount: batches.reduce((a, b) => a + b.count, 0),
    notRunnable: engine.remediationPlan.groups.filter((gr) => gr.status !== 'planned').map((gr) => ({ action: gr.action, status: gr.status, records: gr.count })),
    sampleRequestBody: batches[0] ? { path: batches[0].path, body: { inputs: batches[0].body.inputs.slice(0, 2) } } : null,
    attempted: 0,
    succeeded: 0,
    failed: 0,
    failures: [],
    ok: true,
  },
}];

// ─────────────────────────────────────────────────────────────────────────────
// RevOps Slack Block Kit Alert Builder
// Summarises integrity score, orphan counts, broken links and the remediation
// plan, with deep links to each affected HubSpot record. ≤ 50 blocks, section
// text ≤ 3000 chars. Always built (for preview); sent only when allowed.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const engine = $('Association Integrity & Orphan Detection Engine').first().json;
let write = null;
try { write = $('Collect Remediation Results').first().json; } catch (e) { /* not executed */ }
if (!write) { try { write = $('Dry-Run Remediation Preview').first().json; } catch (e) { /* not executed */ } }

const SEV = ['low', 'medium', 'high', 'critical'];
const ICON = { critical: ':red_circle:', high: ':large_orange_circle:', medium: ':large_yellow_circle:', low: ':white_circle:', none: ':large_green_circle:' };
const TITLES = {
  audit_incomplete: 'Audit incomplete',
  association_definition_missing: 'Association definition missing',
  orphan_child: `Orphaned ${cfg.levels.child.label} records`,
  orphan_asset: `Orphaned ${cfg.levels.asset.label} records`,
  dangling_association: 'Dangling associations (deleted targets)',
  broken_chain: `Broken chains (${cfg.levels.asset.label} → no ${cfg.levels.parent.label})`,
  cardinality_violation: 'Cardinality violations',
  association_label_mismatch: 'Association type/label mismatches',
  asymmetric_association: 'Asymmetric associations',
  empty_parent: `${cfg.levels.parent.label} records with no ${cfg.levels.child.label}`,
};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const clip = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
const minRank = SEV.indexOf(cfg.alertMinSeverity);
const alertIssues = engine.issues.filter((i) => SEV.indexOf(i.severity) >= minRank);
const shouldAlert = alertIssues.length > 0 || engine.runSeverity === 'critical';

const s = engine.stats;
const mode = cfg.modeLabel === 'LIVE' ? ':satellite_antenna: LIVE' : cfg.modeLabel === 'SANDBOX' ? ':test_tube: SANDBOX (synthetic data)' : ':eyes: LIVE DRY RUN';
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: clip(`HubSpot association integrity · ${cfg.runDate}`, 150), emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: clip(`${mode}  ·  Run \`${esc(cfg.runId)}\`  ·  ${ICON[engine.runSeverity] || ''} ${String(engine.runSeverity).toUpperCase()}`, 3000) }] },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: `*Integrity score*\n${engine.integrityScore}% healthy` },
    { type: 'mrkdwn', text: `*Records audited*\n${s.records.parent} ${esc(cfg.levels.parent.label)} · ${s.records.child} ${esc(cfg.levels.child.label)} · ${s.records.asset} ${esc(cfg.levels.asset.label)}` },
    { type: 'mrkdwn', text: `*Orphaned*\n${s.orphans.child} ${esc(cfg.levels.child.label)} · ${s.orphans.asset} ${esc(cfg.levels.asset.label)} (${engine.orphanRatePct}%)` },
    { type: 'mrkdwn', text: `*Broken links*\n${s.issuesByCode.dangling_association || 0} dangling · ${s.issuesByCode.broken_chain || 0} broken chain` },
  ] },
  { type: 'divider' },
];

const grouped = {};
for (const i of alertIssues) (grouped[i.code] = grouped[i.code] || []).push(i);
const codes = Object.keys(grouped).sort((a, b) => SEV.indexOf(grouped[b][0].severity) - SEV.indexOf(grouped[a][0].severity));
for (const code of codes.slice(0, 10)) {
  const list = grouped[code];
  const lines = list.slice(0, 5).map((i) => {
    const who = i.url ? `<${i.url}|${esc(i.recordName)}>` : `*${esc(i.recordName)}*`;
    const fix = i.remediation ? ` _→ ${esc(i.remediation.action.replace(/_/g, ' '))} (${esc(i.remediation.status)})_` : '';
    return `• ${who}: ${esc(i.message)}${fix}`;
  });
  if (list.length > 5) lines.push(`_…and ${list.length - 5} more in the n8n execution log._`);
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(`${ICON[list[0].severity]} *${esc(TITLES[code] || code)}* (${list.length})\n${lines.join('\n')}`, 3000) } });
}

const t = engine.remediationPlan.totals;
let remediationLine;
if (!write) remediationLine = 'Remediation: not evaluated';
else if (write.writeMode === 'live') remediationLine = `Remediation applied: ${write.succeeded}/${write.attempted} change(s) succeeded${write.failures.length ? `, ${write.failures.length} failure(s)` : ''}.`;
else remediationLine = `Remediation preview only (${esc(write.blockedReason)}): ${write.wouldChangeCount} change(s) would run.`;
blocks.push({ type: 'divider' });
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(`*Remediation plan*  ·  ${t.create_missing_association} re-link · ${t.archive_dangling_association} archive dangling · ${t.flag_records} record flag(s)\n${remediationLine}${engine.mutationGuard.blocked ? `\n:octagonal_sign: Mutation guard: ${esc(engine.mutationGuard.reasons.join('; '))}` : ''}`, 3000) } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Enabled actions: ${esc(cfg.enabledActions.join(', ') || 'none')}  ·  Portal ${esc(cfg.hubspotPortalId)}  ·  Records list: filter *integrity_status ≠ ok* in HubSpot` }] });

const safeBlocks = blocks.slice(0, 50);
const fallback = clip(`[${cfg.modeLabel}] HubSpot association integrity ${engine.runSeverity}: ${s.orphans.total} orphaned, ${s.issuesByCode.dangling_association || 0} dangling, score ${engine.integrityScore}%.`, 3000);

let skipReason = null;
if (!shouldAlert) skipReason = 'no_alert_worthy_issues';
else if (!cfg.sendSlackAlerts) skipReason = 'send_slack_alerts_disabled';
else if (cfg.dryRun) skipReason = 'dry_run';
else if (!cfg.secretsPresent.hasSlackWebhook) skipReason = 'missing_slack_webhook';
const allowSend = cfg.allowSlackSend === true && shouldAlert;

return [{ json: { allowSend, skipReason: allowSend ? null : skipReason, alertIssueCount: alertIssues.length, blockCount: safeBlocks.length, payload: { text: fallback, blocks: safeBlocks, unfurl_links: false, unfurl_media: false } } }];

// ─────────────────────────────────────────────────────────────────────────────
// Slack Alert Skipped
// Records why no Slack message was sent (gate closed or nothing alert-worthy).
// ─────────────────────────────────────────────────────────────────────────────
const b = $input.first().json;
return [{ json: { slackStatus: 'skipped', skipReason: b.skipReason || 'gate_closed', alertIssueCount: b.alertIssueCount, blockCount: b.blockCount } }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// One secret-free audit record per run: effective safety gates, record and
// issue counts, integrity score, remediation outcome, Slack outcome,
// warnings/errors and a deterministic checksum. Decides whether the ops
// alert should fire (only if the SEND_OPS_ALERTS gate is open).
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json;
const engine = $('Association Integrity & Orphan Detection Engine').first().json;
const slackBuild = $('RevOps Slack Block Kit Builder').first().json;
let write = null;
try { write = $('Collect Remediation Results').first().json; } catch (e) { /* not executed */ }
if (!write) { try { write = $('Dry-Run Remediation Preview').first().json; } catch (e) { /* not executed */ } }

const last = $input.first().json || {};
let slack;
if (last.slackStatus === 'skipped') slack = { status: 'skipped', reason: last.skipReason };
else if (last.error) slack = { status: 'failed', reason: String(typeof last.error === 'string' ? last.error : (last.error.message || 'request failed')).slice(0, 300) };
else slack = { status: String(last.data ?? '').trim() === 'ok' ? 'sent' : 'sent_unconfirmed', blocks: slackBuild.blockCount };

const warnings = [...(cfg.warnings || [])];
const errors = [];
for (const e of engine.fetchMeta.errors || []) (e.nonBlocking ? warnings : errors).push(e.nonBlocking ? `${e.stage}: ${e.message}` : { stage: e.stage, message: e.message });
for (const lvl of Object.keys(engine.fetchMeta.truncated || {})) if (engine.fetchMeta.truncated[lvl]) warnings.push(`${lvl} search was truncated; dangling verdicts for that level are unverified.`);
if (engine.mutationGuard.blocked) warnings.push(`Mutation guard blocked remediation: ${engine.mutationGuard.reasons.join('; ')}`);
for (const i of engine.issues.filter((x) => x.code === 'audit_incomplete' || x.code === 'association_definition_missing')) errors.push({ stage: 'engine', code: i.code, message: i.message });
if (write && write.failures && write.failures.length) write.failures.forEach((f) => errors.push({ stage: 'hubspot_remediation', action: f.action, message: f.message }));
if (slack.status === 'failed') errors.push({ stage: 'slack', message: slack.reason });

const status = errors.length ? 'completed_with_errors' : warnings.length ? 'completed_with_warnings' : 'success';
const finishedAt = new Date();
const fnv = (str) => { let h = 0x811c9dc5; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };
const issueIds = engine.issues.map((i) => i.id).sort();

const audit = {
  runId: cfg.runId,
  workflow: 'n8n-hubspot-custom-object-multi-level-association-validator',
  status,
  mode: cfg.modeLabel,
  source: engine.source,
  startedAt: cfg.runStartedAt,
  finishedAt: finishedAt.toISOString(),
  durationMs: Math.max(0, finishedAt - new Date(cfg.runStartedAt)),
  safety: {
    sandboxRequested: cfg.sandboxRequested, sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun,
    hubspotMutationsEnabled: cfg.hubspotMutationsEnabled, sendSlackAlerts: cfg.sendSlackAlerts, sendOpsAlerts: cfg.sendOpsAlerts,
    gates: { allowHubspotMutations: cfg.allowHubspotMutations, allowSlackSend: cfg.allowSlackSend, allowOpsAlert: cfg.allowOpsAlert },
    mutationGuard: engine.mutationGuard,
    enabledActions: cfg.enabledActions,
    envAccessible: cfg.envAccessible,
    secretsPresent: cfg.secretsPresent,
  },
  hierarchy: Object.fromEntries(Object.entries(cfg.levels).map(([k, l]) => [k, l.objectType])),
  runSeverity: engine.runSeverity,
  integrityScore: engine.integrityScore,
  orphanRatePct: engine.orphanRatePct,
  stats: engine.stats,
  schemaCheck: engine.schemaCheck,
  remediation: write ? {
    mode: write.writeMode,
    blockedReason: write.blockedReason || null,
    planned: engine.remediationPlan.totals,
    wouldChange: write.wouldChangeCount ?? null,
    attempted: write.attempted, succeeded: write.succeeded, failed: write.failed,
  } : null,
  slack,
  issueIds,
  warnings,
  errors,
  checksum: `fnv1a-${fnv(JSON.stringify({ runId: cfg.runId, issueIds, stats: engine.stats }))}`,
};

const needsOpsAlert = cfg.allowOpsAlert === true && (errors.length > 0 || engine.mutationGuard.blocked);

return [{
  json: {
    ...audit,
    needsOpsAlert,
    opsAlertPayload: needsOpsAlert ? {
      text: `[${cfg.modeLabel}] HubSpot association validator ${status} (${cfg.runId}): ${errors.length} error(s), ${warnings.length} warning(s).`,
      runId: cfg.runId, status, errors: errors.slice(0, 20), warnings: warnings.slice(0, 20),
    } : null,
  },
}];
